"""Anharmonic S3 orbit of a cross-ratio and its p-adic factorization."""
from __future__ import annotations
from fractions import Fraction
from typing import List


def padic_valuation(p: int, x: Fraction) -> float:
    if x == 0:
        return float("inf")
    num, den, val = x.numerator, x.denominator, 0
    while num % p == 0:
        num //= p; val += 1
    while den % p == 0:
        den //= p; val -= 1
    return float(val)


def anharmonic_orbit(lam: Fraction) -> List[Fraction]:
    """The six-element orbit of lambda under the anharmonic S3 action."""
    return [lam, 1 - lam, 1 / lam, 1 / (1 - lam),
            (lam - 1) / lam, lam / (lam - 1)]


def main() -> None:
    p = 3
    lam = Fraction(9, 2)   # v_3(lambda) = 2
    print(f"lambda = {lam}, v_{p}(lambda) = {padic_valuation(p, lam)}")
    print("Anharmonic orbit and valuations:")
    for mu in anharmonic_orbit(lam):
        print(f"  {str(mu):>10}   v_{p} = {padic_valuation(p, mu)}")


if __name__ == "__main__":
    main()

"""Gram-matrix view of the global obstruction on random Heegner classes."""
from __future__ import annotations
import random
from typing import List, Sequence


def inner(u: Sequence[float], v: Sequence[float]) -> float:
    return sum(a * b for a, b in zip(u, v))


def obstruction(D: Sequence[float], E: Sequence[float]) -> float:
    return inner(D, D) * inner(E, E) - inner(D, E) ** 2


def gram_det(D: Sequence[float], E: Sequence[float]) -> float:
    """2x2 Gram determinant equals the obstruction, by definition."""
    return inner(D, D) * inner(E, E) - inner(D, E) * inner(E, D)


def main() -> None:
    random.seed(42)
    dim = 4
    print("Random Heegner classes: Obs(D,E) >= 0 and equals Gram determinant")
    min_obs = float("inf")
    for _ in range(6):
        D = [random.uniform(-3, 3) for _ in range(dim)]
        E = [random.uniform(-3, 3) for _ in range(dim)]
        obs, gram = obstruction(D, E), gram_det(D, E)
        min_obs = min(min_obs, obs)
        print(f"  Obs = {obs:10.4f}   Gram = {gram:10.4f}   match={abs(obs-gram)<1e-9}")
    print(f"minimum observed obstruction: {min_obs:.4f} (must be >= 0)")


if __name__ == "__main__":
    main()

"""Telescoping check: valuation factorization is stable under S3 relabelling."""
from __future__ import annotations
from fractions import Fraction


def padic_valuation(p: int, x: Fraction) -> float:
    if x == 0:
        return float("inf")
    n, d, v = x.numerator, x.denominator, 0
    while n % p == 0:
        n //= p; v += 1
    while d % p == 0:
        d //= p; v -= 1
    return float(v)


def cross_ratio(a, b, c, d):
    return ((a - c) * (b - d)) / ((a - d) * (b - c))


def main() -> None:
    p = 7
    a, b, c, d = Fraction(0), Fraction(49), Fraction(7), Fraction(1)
    lam = cross_ratio(a, b, c, d)
    # inversion: (a,b;d,c) = 1/lambda  =>  v_p negates
    inv = cross_ratio(a, b, d, c)
    print(f"v_{p}(lambda)      = {padic_valuation(p, lam)}")
    print(f"v_{p}(1/lambda)    = {padic_valuation(p, inv)}  (equals -v_p(lambda))")
    assert padic_valuation(p, inv) == -padic_valuation(p, lam)
    # complementation: (a,c;b,d) = 1 - lambda
    comp = cross_ratio(a, c, b, d)
    print(f"1 - lambda        = {1 - lam},  (a,c;b,d) = {comp}")
    assert comp == 1 - lam
    print("anharmonic relations verified")


if __name__ == "__main__":
    main()

